const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const text = buf.toString('utf8');

const CVE_RE = /^CVE-\d{4}-\d{4,7}$/i;
const seen = new Set();
const out = [];

for (const rawLine of text.split(/\r?\n/)) {
  const line = rawLine.trim();
  if (!line || line.startsWith('#')) continue;      // blank lines / comments
  const id = line.toUpperCase();
  if (!CVE_RE.test(id)) continue;                   // skip malformed entries
  if (seen.has(id)) continue;                        // dedupe
  seen.add(id);
  out.push({ json: { cve_id: id } });
}

// Fail loudly rather than silently writing an empty report.
if (out.length === 0) {
  throw new Error(
    'No valid CVE IDs found in cve_ids.txt. ' +
    'Format: one CVE ID per line, e.g. CVE-2024-3400. Lines starting with # are ignored. ' +
    'Checked path: /opt/n8n/cvss_monitor/cve_ids.txt'
  );
}

return out;

// Correlates each NVD response back to the CVE ID that was requested (by
// position, since the NVD single-cveId endpoint returns one object per
// call, never an array, so input/output items stay 1:1).
const inputIds = $('Parse CVE IDs').all().map(i => i.json.cve_id);
const rows = $input.all();
const now = new Date().toISOString();

function pickMetric(metrics) {
  if (!metrics) return null;
  const order = ['cvssMetricV31', 'cvssMetricV30', 'cvssMetricV2'];
  for (const key of order) {
    if (Array.isArray(metrics[key]) && metrics[key].length) {
      const primary = metrics[key].find(m => m.type === 'Primary') || metrics[key][0];
      return { key, m: primary };
    }
  }
  return null;
}

const blank = (cve_id, status, error_detail) => ({ json: {
  cve_id, status, error_detail,
  published: '', last_modified: '', description: '',
  cvss_version: '', base_score: '', base_severity: '', vector_string: '',
  exploitability_score: '', impact_score: '', vuln_status: '', fetched_at: now
}});

const out = [];
for (let idx = 0; idx < rows.length; idx++) {
  const r = rows[idx].json || {};
  const fallbackId = inputIds[idx] || '';

  // HTTP Request node was set to "Continue (using error output: off) /
  // On Error: Continue" so a failed call lands here with an error field
  // instead of stopping the whole run.
  const err = r.error || r.errorMessage;
  if (err || r.message) {
    out.push(blank(fallbackId, 'ERROR', String(err || r.message).slice(0, 300)));
    continue;
  }

  const vulns = Array.isArray(r.vulnerabilities) ? r.vulnerabilities : [];
  if (vulns.length === 0) {
    out.push(blank(fallbackId, 'NOT_FOUND', ''));
    continue;
  }

  const cve = vulns[0].cve || {};
  const cveId = cve.id || fallbackId;
  const vulnStatus = cve.vulnStatus || '';
  const descObj = (cve.descriptions || []).find(d => d.lang === 'en') || (cve.descriptions || [])[0] || {};
  const description = (descObj.value || '').replace(/\s+/g, ' ').trim().slice(0, 500);

  const picked = pickMetric(cve.metrics);
  let cvssVersion = '', baseScore = '', baseSeverity = '', vectorString = '', exploitability = '', impact = '';
  if (picked) {
    const cd = picked.m.cvssData || {};
    cvssVersion = cd.version || picked.key.replace('cvssMetric', '');
    baseScore = cd.baseScore ?? '';
    baseSeverity = cd.baseSeverity || picked.m.baseSeverity || '';
    vectorString = cd.vectorString || '';
    exploitability = picked.m.exploitabilityScore ?? '';
    impact = picked.m.impactScore ?? '';
  }

  out.push({ json: {
    cve_id: cveId,
    status: vulnStatus === 'Rejected' ? 'REJECTED' : 'FOUND',
    error_detail: '',
    published: cve.published || '',
    last_modified: cve.lastModified || '',
    description,
    cvss_version: cvssVersion,
    base_score: baseScore,
    base_severity: baseSeverity,
    vector_string: vectorString,
    exploitability_score: exploitability,
    impact_score: impact,
    vuln_status: vulnStatus,
    fetched_at: now
  }});
}

// Sort worst-first so the report is useful to read top to bottom.
out.sort((a, b) => (Number(b.json.base_score) || -1) - (Number(a.json.base_score) || -1));
return out;

const rows = $input.all().map(i => i.json);
const counts = rows.reduce((acc, r) => {
  acc[r.status] = (acc[r.status] || 0) + 1;
  return acc;
}, {});
const critical = rows.filter(r => r.status === 'FOUND' && Number(r.base_score) >= 9).length;

return [{ json: {
  run_date: new Date().toISOString(),
  total_checked: rows.length,
  found: counts.FOUND || 0,
  not_found: counts.NOT_FOUND || 0,
  rejected: counts.REJECTED || 0,
  errors: counts.ERROR || 0,
  critical_9_plus: critical
}}];
